def transform(grid):
    colors=set(v for row in grid for v in row)-{0}
    candidates=[]
    for color in colors:
        cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        h=r1-r0+1; w=c1-c0+1
        pts={(r-r0,c-c0) for r,c in cells}
        exact=False
        if h==w:
            n=h
            for k in range(4):
                tri={(r,c) for r in range(n) for c in range(n) if [c<=r,c>=r,c+r<=n-1,c+r>=n-1][k]}
                if pts==tri: exact=True
        score=(exact, -abs(len(cells)-h*(h+1)//2),len(cells))
        candidates.append((score,color,r0,r1,c0,c1))
    _,color,r0,r1,c0,c1=max(candidates)
    return [[color if grid[r][c]==color else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]

